(() => {
  let dark=false;try{dark=localStorage.getItem('platform-theme')==='dark';}catch{}
  const videoNotes=[{time:12.4,author:'Maya',text:'Hold this opening frame a little longer.'},{time:47.8,author:'Jon',text:'Use the alternate performance here.'},{time:83.2,author:'Andrew',text:'Music edit should land on this cut.'}];
  let videoTime=47.8,playing=false,timer;
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const tc=s=>{const fps=24,whole=Math.floor(s),frames=Math.floor((s-whole)*fps);return `00:${String(Math.floor(whole/60)).padStart(2,'0')}:${String(whole%60).padStart(2,'0')}:${String(frames).padStart(2,'0')}`;};
  function header(){return `<header class="top"><a class="brand" href="/">platform<b>.</b></a><nav class="ecosystem-nav" aria-label="Platform media spaces"><a href="/">Audio</a><a class="active" href="/video.html">Video</a></nav><div class="crumb">Campaign Film / Picture Lock</div><div class="top-actions"><button class="btn" id="theme-toggle">Dark mode</button><button class="btn primary" id="copy-link">Copy view link</button></div></header>`;}
  function left(){return `<aside class="eco-side video-files"><a class="project" href="/video.html"><strong>Campaign Film</strong><small>Video project · 6 collaborators</small><span class="browse-label">View project overview</span></a><div class="section-title">PROJECT FILES</div><nav class="nav-tree" aria-label="Video project files"><ul><li><div class="nav-row"><button class="twisty" data-video-toggle="picture-lock" aria-label="Collapse Picture Lock" aria-expanded="true">⌄</button><a href="/video.html">01 — Picture Lock</a></div><ul id="picture-lock"><li><div class="nav-row"><button class="twisty" data-video-toggle="cuts" aria-label="Collapse Cuts" aria-expanded="true">⌄</button><a href="/video.html">Cuts</a></div><ul id="cuts"><li><div class="nav-row active"><span class="twisty">∿</span><a href="/video.html" aria-current="page">Film v6<span class="nav-current">Current</span></a></div></li><li><div class="nav-row"><span class="twisty">∿</span><a href="/video.html">Film v5</a></div></li><li><div class="nav-row"><span class="twisty">∿</span><a href="/video.html">Film v4</a></div></li></ul></li><li><div class="nav-row"><span class="twisty">›</span><a href="/video.html">Audio</a></div></li><li><div class="nav-row"><span class="twisty">›</span><a href="/video.html">Graphics</a></div></li><li><div class="nav-row"><span class="twisty">›</span><a href="/video.html">Captions</a></div></li></ul></li><li><div class="nav-row"><span class="twisty">›</span><a href="/video.html">02 — Social Cutdowns</a></div></li><li><div class="nav-row"><span class="twisty">›</span><a href="/video.html">References</a></div></li><li><div class="nav-row"><span class="twisty">›</span><a href="/video.html">Deliverables</a></div></li></ul></nav><div class="demo-note">Sample project · Explore freely</div></aside>`;}
  function integrations(apps){return `<section class="integration-section"><h2>Creative app adapters</h2><div class="integration-grid">${apps.map(([id,name,detail])=>`<button class="integration-card" data-bridge="${id}"><span><strong>${name}</strong><small>${detail}</small></span><span class="bridge-badge">Bridge export</span></button>`).join('')}</div><p class="eco-footer-note">These buttons generate structured review data for an integration adapter; they do not launch or authenticate the desktop apps in this prototype.</p></section>`;}
  function videoMain(){return `<main class="eco-main"><div class="eco-title"><div><h1>Campaign Film — Picture Lock</h1><p>Film v6 · 1920×1080 · 23.976 fps · Current review</p></div><div class="eco-versions"><button class="version active">V6 · Current</button><button class="version">V5</button><button class="version">V4</button></div></div><div class="video-stage"><div class="video-scene"></div><span class="timecode" id="video-timecode">${tc(videoTime)}</span></div><div class="eco-transport"><button class="btn" id="video-back">−5 sec</button><button class="play" id="video-play">▶</button><button class="btn" id="video-forward">+5 sec</button></div><div class="eco-timeline" id="video-timeline"><div id="video-markers"></div><div class="timeline-cursor" id="video-cursor"></div><div class="video-track"><span class="clip"></span><span class="clip"></span><span class="clip"></span><span class="clip"></span></div><div class="video-track"><span class="clip audio"></span><span class="clip audio"></span></div></div>${integrations([['premiere','Adobe Premiere Pro','Marker CSV + panel payload'],['avid','Avid Media Composer','Locator bridge text'],['resolve','DaVinci Resolve','Timeline marker CSV'],['finalcut','Final Cut Pro','FCPXML annotation bridge']])}</main>`;}
  function videoRight(){return `<aside class="eco-side right"><div class="right-head"><h2>Picture notes</h2><span class="count">${videoNotes.length} open</span></div><div id="eco-notes">${videoNotes.map((n,i)=>`<article class="eco-note" data-video-note="${i}" tabindex="0"><b>${esc(n.author)}</b> <span class="stamp">${tc(n.time)}</span><p>${esc(n.text)}</p><small>Film v6 · Open</small></article>`).join('')}</div><form class="note-form" id="video-note-form"><input id="video-note" placeholder="Add note at ${tc(videoTime)}" required><button class="btn" type="submit">Add timeline note</button></form></aside>`;}
  function applyTheme(){document.body.classList.toggle('dark-mode',dark);const b=document.getElementById('theme-toggle');b.textContent=dark?'Light mode':'Dark mode';b.setAttribute('aria-pressed',String(dark));}
  function downloadBridge(app){const data={schema:'platform.review-bridge.v1',workspace:'video',target_app:app,asset:'Campaign Film — Film v6',timebase:{fps:23.976},annotations:videoNotes,prototype:true},blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`platform-video-${app}-bridge.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function bindCommon(){applyTheme();document.getElementById('theme-toggle').onclick=()=>{dark=!dark;try{localStorage.setItem('platform-theme',dark?'dark':'light');}catch{}applyTheme();};document.getElementById('copy-link').onclick=async e=>{try{await navigator.clipboard.writeText(location.href);e.target.textContent='Link copied';}catch{prompt('Copy this view link:',location.href);}};document.querySelectorAll('[data-bridge]').forEach(b=>b.onclick=()=>downloadBridge(b.dataset.bridge));document.querySelectorAll('.eco-versions .version').forEach(b=>b.onclick=()=>{document.querySelectorAll('.eco-versions .version').forEach(x=>x.classList.remove('active'));b.classList.add('active');});}
  function renderVideoMarkers(){const box=document.getElementById('video-markers');box.innerHTML=videoNotes.map((n,i)=>`<button class="eco-marker" style="left:${n.time/120*100}%" data-video-marker="${i}" aria-label="Open video note ${i+1}">${i+1}</button>`).join('');box.querySelectorAll('[data-video-marker]').forEach(b=>b.onclick=e=>{e.stopPropagation();seekVideo(videoNotes[+b.dataset.videoMarker].time);highlight(`[data-video-note="${b.dataset.videoMarker}"]`);});}
  function seekVideo(s){videoTime=Math.max(0,Math.min(120,s));document.getElementById('video-cursor').style.left=videoTime/120*100+'%';document.getElementById('video-timecode').textContent=tc(videoTime);document.getElementById('video-note').placeholder='Add note at '+tc(videoTime);}
  function highlight(sel){const el=document.querySelector(sel);if(!el)return;if(!matchMedia?.('(prefers-reduced-motion: reduce)').matches)el.animate([{background:'rgba(105,82,185,.2)',boxShadow:'inset 3px 0 #6650b7'},{background:'transparent',boxShadow:'inset 3px 0 transparent'}],{duration:1200,easing:'ease-out'});el.scrollIntoView({behavior:'smooth',block:'center'});}
  function bindVideo(){renderVideoMarkers();seekVideo(videoTime);document.getElementById('video-timeline').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();seekVideo((e.clientX-r.left)/r.width*120);};document.getElementById('video-back').onclick=()=>seekVideo(videoTime-5);document.getElementById('video-forward').onclick=()=>seekVideo(videoTime+5);document.getElementById('video-play').onclick=e=>{if(playing){clearInterval(timer);playing=false;e.target.textContent='▶';return;}playing=true;e.target.textContent='Ⅱ';timer=setInterval(()=>{seekVideo(videoTime+.25);if(videoTime>=120){clearInterval(timer);playing=false;e.target.textContent='▶';}},250);};document.querySelectorAll('[data-video-note]').forEach(n=>n.onclick=()=>seekVideo(videoNotes[+n.dataset.videoNote].time));document.getElementById('video-note-form').onsubmit=e=>{e.preventDefault();videoNotes.push({time:videoTime,author:'You',text:document.getElementById('video-note').value.trim()});render();};}
  function bindTree(){document.querySelectorAll('[data-video-toggle]').forEach(button=>button.onclick=()=>{const group=document.getElementById(button.dataset.videoToggle),expanded=button.getAttribute('aria-expanded')==='true';group.hidden=expanded;button.setAttribute('aria-expanded',String(!expanded));button.textContent=expanded?'›':'⌄';button.setAttribute('aria-label',(expanded?'Expand ':'Collapse ')+button.dataset.videoToggle.replace(/-/g,' '));});}
  function render(){clearInterval(timer);playing=false;document.getElementById('ecosystem-app').innerHTML=header()+`<div class="eco-layout">${left()}${videoMain()}${videoRight()}</div>`;bindCommon();bindTree();bindVideo();}
  render();
})();
